import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CXsxtpvq.js";const s="/asset-studio/shots/en/07-library-character.webp",i="/asset-studio/shots/en/08-library-outfit-set.webp",g=JSON.parse('{"title":"Prompt library","description":"","frontmatter":{},"headers":[],"relativePath":"guide/library.md","filePath":"guide/library.md"}'),n={name:"guide/library.md"};function d(l,e,h,p,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="prompt-library" tabindex="-1">Prompt library <a class="header-anchor" href="#prompt-library" aria-label="Permalink to &quot;Prompt library&quot;">​</a></h1><p>The <strong>Prompts</strong> menu keeps prompts as reusable pieces. When you generate, the chosen pieces are joined in a fixed order into one prompt.</p><h2 id="work-›-character-›-outfit" tabindex="-1">Work › character › outfit <a class="header-anchor" href="#work-›-character-›-outfit" aria-label="Permalink to &quot;Work › character › outfit&quot;">​</a></h2><p>Everything lives under a <strong>work</strong>. Character codes (C001 and so on) are numbered per work, so the same code in two works means two different characters.</p><ul><li><strong>+ Work</strong> creates a work. It can carry a prompt shared by the whole work (for example <code>fantasy</code>).</li><li><strong>+ Character</strong> adds a character with its appearance prompt. Put only what never changes with the outfit: hair and eye colour, build and so on.</li></ul><p><img src="'+s+'" alt="Character appearance"></p><p>Prompt fields take one tag or one sentence per line. You can paste comma-separated tags too; <strong>Tidy lines</strong> splits them one per line. Danbooru tag autocomplete helps while you type (it can be turned off in Settings).</p><h2 id="kinds-of-pieces" tabindex="-1">Kinds of pieces <a class="header-anchor" href="#kinds-of-pieces" aria-label="Permalink to &quot;Kinds of pieces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Examples</th><th>Notes</th></tr></thead><tbody><tr><td>Outfit</td><td>top, bottom, shoes, hands, all</td><td>Made per slot and grouped into outfit sets.</td></tr><tr><td>Expression</td><td>smile, surprised, thinking</td><td>General (SFW) and adult (NSFW). Each can name a default composition.</td></tr><tr><td>Composition</td><td>upper body, full body</td><td>Each suggests which outfit slots to include (upper body: hands and top).</td></tr><tr><td>Style</td><td>artist tags</td><td>Chosen when you generate.</td></tr><tr><td>Common</td><td>quality tags (positive), negative tags</td><td>Added to every image.</td></tr></tbody></table><h2 id="outfit-sets" tabindex="-1">Outfit sets <a class="header-anchor" href="#outfit-sets" aria-label="Permalink to &quot;Outfit sets&quot;">​</a></h2><p><strong>+ Outfit set</strong> groups outfit pieces by slot into one outfit. When you generate, only the slots that fit the composition are included, so shoe tags do not pull an upper-body image off frame.</p><p><img src="'+i+'" alt="Outfit set: pieces by slot"></p><h2 id="scope-global-·-shared-in-work-·-character" tabindex="-1">Scope: Global · Shared in work · Character <a class="header-anchor" href="#scope-global-·-shared-in-work-·-character" aria-label="Permalink to &quot;Scope: Global · Shared in work · Character&quot;">​</a></h2><p>The scope buttons at the top left decide who can use a piece.</p><ul><li><strong>Global</strong>: every work (for example quality tags).</li><li><strong>Shared in work</strong>: every character of that work (for example the sample&#39;s five expressions).</li><li><strong>Character</strong>: only that character (for example Lyra&#39;s uniform).</li></ul><p>When pieces with the same code exist in several scopes, the closest one wins: character, then shared in work, then global.</p><h2 id="model-family-marks" tabindex="-1">Model family marks <a class="header-anchor" href="#model-family-marks" aria-label="Permalink to &quot;Model family marks&quot;">​</a></h2><p>Every piece is marked <strong>Anima</strong>, <strong>SDXL·IL</strong> or <strong>Shared</strong>. The Jobs menu shows only pieces that match the chosen model family, plus shared ones, so sentence-style Anima prompts do not end up in SDXL generations.</p><h2 id="deleting-and-the-trash" tabindex="-1">Deleting and the trash <a class="header-anchor" href="#deleting-and-the-trash" aria-label="Permalink to &quot;Deleting and the trash&quot;">​</a></h2><p>Deleted pieces go to the library <strong>Trash</strong>, from where they can be restored.</p>',20)])])}const f=t(n,[["render",d]]);export{g as __pageData,f as default};
